import { createComponent, Types, defineComponents } from '@iwsdk/core';

export const Ship = createComponent('Ship', {
  speed: { type: Types.Float32, default: 0.8 },
  headingAngle: { type: Types.Float32, default: 0 },
  isLit: { type: Types.Boolean, default: false },
  litTimer: { type: Types.Float32, default: 0 },
  docked: { type: Types.Boolean, default: false },
  sinking: { type: Types.Boolean, default: false },
  sinkProgress: { type: Types.Float32, default: 0 },
  spawnAngle: { type: Types.Float32, default: 0 },
  shipType: { type: Types.Int32, default: 0 }, // 0=fishing, 1=cargo, 2=ferry
  points: { type: Types.Int32, default: 100 },
});

export const Rock = createComponent('Rock', {
  damageRadius: { type: Types.Float32, default: 1.5 },
});

export const Harbor = createComponent('Harbor', {
  dockRadius: { type: Types.Float32, default: 3.0 },
});

export const LighthouseBeam = createComponent('LighthouseBeam', {
  range: { type: Types.Float32, default: 60 },
  coneAngle: { type: Types.Float32, default: 0.18 },
  active: { type: Types.Boolean, default: true },
});

export const StarField = createComponent('StarField', {
  count: { type: Types.Int32, default: 400 },
});

export const OceanTile = createComponent('OceanTile', {
  waveSpeed: { type: Types.Float32, default: 1.0 },
});

export const Flare = createComponent('Flare', {
  life: { type: Types.Float32, default: 2.0 },
  speed: { type: Types.Float32, default: 8.0 },
});

export default defineComponents([
  Ship,
  Rock,
  Harbor,
  LighthouseBeam,
  StarField,
  OceanTile,
  Flare,
]);

import { World } from '@iwsdk/core';
import projectOptions from 'virtual:iwsdk-project';
import { EnvironmentSystem } from './environment-system.js';
import { LighthouseSystem } from './lighthouse-system.js';
import { ShipSystem } from './ship-system.js';
import { AudioSystem } from './audio-system.js';
import { GameSystem } from './game-system.js';

World.create(
  document.getElementById('scene-container') as HTMLDivElement,
  projectOptions,
).then((world) => {
  // Register in dependency order
  world.registerSystem(AudioSystem);
  world.registerSystem(EnvironmentSystem);
  world.registerSystem(LighthouseSystem);
  world.registerSystem(ShipSystem);
  world.registerSystem(GameSystem);
});

import { AssetType, defineAssets } from '@iwsdk/core';

const publicAssetUrl = (filePath: string): string =>
  `${import.meta.env.BASE_URL}${filePath.replace(/^\/+/u, '')}`;

export default defineAssets({
  'menu-panel': {
    url: publicAssetUrl('ui/menu.uikitml'),
    type: AssetType.UIKitML,
    name: 'Menu Panel',
  },
  'hud-panel': {
    url: publicAssetUrl('ui/hud.uikitml'),
    type: AssetType.UIKitML,
    name: 'HUD Panel',
  },
  'wave-complete-panel': {
    url: publicAssetUrl('ui/wave-complete.uikitml'),
    type: AssetType.UIKitML,
    name: 'Wave Complete Panel',
  },
  'game-over-panel': {
    url: publicAssetUrl('ui/game-over.uikitml'),
    type: AssetType.UIKitML,
    name: 'Game Over Panel',
  },
  'settings-panel': {
    url: publicAssetUrl('ui/settings.uikitml'),
    type: AssetType.UIKitML,
    name: 'Settings Panel',
  },
  'tutorial-panel': {
    url: publicAssetUrl('ui/tutorial.uikitml'),
    type: AssetType.UIKitML,
    name: 'Tutorial Panel',
  },
  'compass-panel': {
    url: publicAssetUrl('ui/compass.uikitml'),
    type: AssetType.UIKitML,
    name: 'Compass Panel',
  },
});

import {
  createSystem,
  World,
  Vector3,
  Mesh,
  PlaneGeometry,
  ShaderMaterial,
  CylinderGeometry,
  MeshStandardMaterial,
  SphereGeometry,
  ConeGeometry,
  BoxGeometry,
  PointLight,
  AmbientLight,
  FogExp2,
  BufferGeometry,
  BufferAttribute,
  Points,
  PointsMaterial,
  MeshBasicMaterial,
  Color,
  DoubleSide,
  AdditiveBlending,
  Group,
  TorusGeometry,
  RingGeometry,
  Float32BufferAttribute,
} from '@iwsdk/core';

const OCEAN_SIZE = 200;
const OCEAN_SEGMENTS = 80;
const LIGHTHOUSE_HEIGHT = 10;
const HARBOR_POS = new Vector3(8, 0, -5);
const NUM_ROCKS = 12;
const STAR_COUNT = 600;
const RAIN_COUNT = 2000;
const NUM_BUOYS = 6;

export class EnvironmentSystem extends createSystem({}) {
  private oceanMesh!: Mesh;
  private oceanGeo!: PlaneGeometry;
  private posAttr!: BufferAttribute;
  private origY!: Float32Array;
  private fogDensity = 0.012;
  private targetFogDensity = 0.012;
  private harborLights: PointLight[] = [];
  private starPoints!: Points;
  private lighthouseGroup!: Group;
  private lanternLight!: PointLight;
  private lanternMesh!: Mesh;

  // Weather
  private rainPoints!: Points;
  private rainPositions!: Float32Array;
  private rainActive = false;
  private lightningTimer = 0;
  private lightningFlash!: AmbientLight;
  private lightningActive = false;
  private windStrength = 0;
  private targetWindStrength = 0;

  // Sky color shifting
  private skyDome!: Color;
  private targetSkyColor = new Color(0x010818);
  private currentSkyColor = new Color(0x010818);

  // Moon and clouds
  private moonMesh!: Mesh;
  private cloudMeshes: Mesh[] = [];

  // Rock foam
  private foamMeshes: Mesh[] = [];

  // Buoys
  private buoyGroups: Group[] = [];
  private buoyLights: PointLight[] = [];
  private buoysVisible = true;

  // Exposed for other systems
  public rockPositions: Vector3[] = [];
  public harborPosition = HARBOR_POS.clone();

  // Horizon glow
  private horizonGlowMesh!: Mesh;

  init() {
    this.buildOcean();
    this.buildLighthouse();
    this.buildHarbor();
    this.buildRocks();
    this.buildStarfield();
    this.buildLighting();
    this.buildMoon();
    this.buildClouds();
    this.buildRainSystem();
    this.buildBuoys();
    this.buildHorizonGlow();
  }

  private buildOcean() {
    const geo = new PlaneGeometry(OCEAN_SIZE, OCEAN_SIZE, OCEAN_SEGMENTS, OCEAN_SEGMENTS);
    geo.rotateX(-Math.PI / 2);
    const mat = new ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uDeepColor: { value: new Color(0x001428) },
        uShallowColor: { value: new Color(0x003344) },
        uFoamColor: { value: new Color(0x00ffcc) },
        uWindStrength: { value: 0 },
      },
      vertexShader: `
        uniform float uTime;
        uniform float uWindStrength;
        varying vec2 vUv;
        varying float vElevation;
        void main() {
          vUv = uv;
          vec3 pos = position;
          float windWave = sin(pos.x * 0.3 + uTime * 2.0) * uWindStrength * 0.5;
          float wave1 = sin(pos.x * 0.15 + uTime * 0.8) * 0.3;
          float wave2 = sin(pos.z * 0.12 + uTime * 0.6) * 0.25;
          float wave3 = sin((pos.x + pos.z) * 0.08 + uTime * 1.1) * 0.15;
          pos.y += wave1 + wave2 + wave3 + windWave;
          vElevation = wave1 + wave2 + wave3 + windWave;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 uDeepColor;
        uniform vec3 uShallowColor;
        uniform vec3 uFoamColor;
        varying vec2 vUv;
        varying float vElevation;
        void main() {
          float depth = smoothstep(-0.4, 0.5, vElevation);
          vec3 col = mix(uDeepColor, uShallowColor, depth);
          float foam = smoothstep(0.35, 0.5, vElevation);
          col = mix(col, uFoamColor, foam * 0.15);
          gl_FragColor = vec4(col, 0.92);
        }
      `,
      transparent: true,
      side: DoubleSide,
    });
    this.oceanMesh = new Mesh(geo, mat);
    this.oceanGeo = geo;
    this.posAttr = geo.getAttribute('position') as BufferAttribute;
    this.origY = new Float32Array(this.posAttr.count);
    for (let i = 0; i < this.posAttr.count; i++) {
      this.origY[i] = this.posAttr.getY(i);
    }
    const oceanEntity = this.world.createTransformEntity(this.oceanMesh);
    oceanEntity.object3D!.position.set(0, -0.2, 0);

    this.world.scene.fog = new FogExp2(0x010818, this.fogDensity);
  }

  private buildLighthouse() {
    this.lighthouseGroup = new Group();

    // Tower base
    const baseMat = new MeshStandardMaterial({ color: 0x334455, roughness: 0.8 });
    const baseGeo = new CylinderGeometry(2.5, 3.0, 2, 12);
    const baseMesh = new Mesh(baseGeo, baseMat);
    baseMesh.position.set(0, 1, 0);
    this.lighthouseGroup.add(baseMesh);

    // Tower body
    const towerMat = new MeshStandardMaterial({ color: 0xcccccc, roughness: 0.6 });
    const towerGeo = new CylinderGeometry(1.5, 2.2, LIGHTHOUSE_HEIGHT - 2, 12);
    const towerMesh = new Mesh(towerGeo, towerMat);
    towerMesh.position.set(0, (LIGHTHOUSE_HEIGHT - 2) / 2 + 2, 0);
    this.lighthouseGroup.add(towerMesh);

    // Red stripe bands
    const stripeMat = new MeshStandardMaterial({ color: 0xcc2222, roughness: 0.5 });
    for (let i = 0; i < 3; i++) {
      const stripeGeo = new CylinderGeometry(
        1.5 + (2 - i) * 0.15,
        1.5 + (2 - i) * 0.2,
        0.6,
        12,
      );
      const stripe = new Mesh(stripeGeo, stripeMat);
      stripe.position.set(0, 3 + i * 2.5, 0);
      this.lighthouseGroup.add(stripe);
    }

    // Lantern room
    const lanternMat = new MeshStandardMaterial({
      color: 0xffcc44,
      emissive: 0xffaa22,
      emissiveIntensity: 0.5,
      transparent: true,
      opacity: 0.7,
    });
    const lanternGeo = new CylinderGeometry(1.8, 1.8, 1.5, 8);
    this.lanternMesh = new Mesh(lanternGeo, lanternMat);
    this.lanternMesh.position.set(0, LIGHTHOUSE_HEIGHT + 0.75, 0);
    this.lighthouseGroup.add(this.lanternMesh);

    // Lantern cap
    const capMat = new MeshStandardMaterial({ color: 0x222222 });
    const capGeo = new ConeGeometry(2.0, 1.5, 8);
    const capMesh = new Mesh(capGeo, capMat);
    capMesh.position.set(0, LIGHTHOUSE_HEIGHT + 2.25, 0);
    this.lighthouseGroup.add(capMesh);

    // Lantern light
    this.lanternLight = new PointLight(0xffaa22, 3, 30);
    this.lanternLight.position.set(0, LIGHTHOUSE_HEIGHT + 0.75, 0);
    this.lighthouseGroup.add(this.lanternLight);

    // Railing
    const railMat = new MeshStandardMaterial({ color: 0x444444 });
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2;
      const railGeo = new CylinderGeometry(0.05, 0.05, 1.2, 4);
      const railPost = new Mesh(railGeo, railMat);
      railPost.position.set(
        Math.cos(angle) * 2.0,
        LIGHTHOUSE_HEIGHT + 0.1,
        Math.sin(angle) * 2.0,
      );
      this.lighthouseGroup.add(railPost);
    }

    const entity = this.world.createTransformEntity(this.lighthouseGroup);
    entity.object3D!.position.set(0, 0, 0);
  }

  private buildHarbor() {
    const harborGroup = new Group();

    const pierMat = new MeshStandardMaterial({ color: 0x664422, roughness: 0.9 });
    const pierGeo = new BoxGeometry(8, 0.5, 3);
    const pierMesh = new Mesh(pierGeo, pierMat);
    pierMesh.position.set(0, 0.3, 0);
    harborGroup.add(pierMesh);

    const supportMat = new MeshStandardMaterial({ color: 0x553311 });
    for (let x = -3; x <= 3; x += 2) {
      const supportGeo = new CylinderGeometry(0.15, 0.15, 2, 6);
      const support = new Mesh(supportGeo, supportMat);
      support.position.set(x, -0.7, 0);
      harborGroup.add(support);
    }

    const lightColors = [0x00ff44, 0xff2222, 0x00ff44];
    for (let i = 0; i < 3; i++) {
      const lightGeo = new SphereGeometry(0.15, 8, 8);
      const lightMat = new MeshBasicMaterial({ color: lightColors[i] });
      const lightMesh = new Mesh(lightGeo, lightMat);
      lightMesh.position.set(-3 + i * 3, 1, 1.5);
      harborGroup.add(lightMesh);

      const pl = new PointLight(lightColors[i], 1, 8);
      pl.position.copy(lightMesh.position);
      harborGroup.add(pl);
      this.harborLights.push(pl);
    }

    const entity = this.world.createTransformEntity(harborGroup);
    entity.object3D!.position.copy(HARBOR_POS);
  }

  private buildRocks() {
    const rockMat = new MeshStandardMaterial({ color: 0x2a2a2a, roughness: 1.0 });
    const foamMat = new MeshBasicMaterial({
      color: 0x88cccc,
      transparent: true,
      opacity: 0.25,
      depthWrite: false,
    });

    const rockPositions = [
      new Vector3(-15, -0.5, -20),
      new Vector3(-25, -0.3, -10),
      new Vector3(20, -0.4, -25),
      new Vector3(-10, -0.6, -35),
      new Vector3(30, -0.3, -15),
      new Vector3(-30, -0.4, -30),
      new Vector3(15, -0.5, -40),
      new Vector3(-20, -0.3, -45),
      new Vector3(25, -0.5, -35),
      new Vector3(-35, -0.6, -20),
      new Vector3(35, -0.4, -40),
      new Vector3(5, -0.3, -50),
    ];

    for (const pos of rockPositions) {
      const rockGroup = new Group();
      const mainSize = 1 + Math.random() * 1.5;
      const mainGeo = new SphereGeometry(mainSize, 6, 5);
      const mainRock = new Mesh(mainGeo, rockMat);
      mainRock.scale.set(1, 0.5 + Math.random() * 0.3, 1);
      rockGroup.add(mainRock);

      for (let j = 0; j < 2; j++) {
        const smallSize = 0.5 + Math.random() * 0.8;
        const smallGeo = new SphereGeometry(smallSize, 5, 4);
        const smallRock = new Mesh(smallGeo, rockMat);
        smallRock.position.set(
          (Math.random() - 0.5) * 2,
          0,
          (Math.random() - 0.5) * 2,
        );
        smallRock.scale.set(1, 0.4 + Math.random() * 0.3, 1);
        rockGroup.add(smallRock);
      }

      // Foam ring around rocks as warning
      const foamGeo = new RingGeometry(mainSize + 0.5, mainSize + 2.0, 16);
      foamGeo.rotateX(-Math.PI / 2);
      const foamMesh = new Mesh(foamGeo, foamMat.clone());
      foamMesh.position.set(0, 0.05, 0);
      rockGroup.add(foamMesh);
      this.foamMeshes.push(foamMesh);

      const entity = this.world.createTransformEntity(rockGroup);
      entity.object3D!.position.copy(pos);
      this.rockPositions.push(pos.clone());
    }
  }

  private buildStarfield() {
    const positions = new Float32Array(STAR_COUNT * 3);
    const sizes = new Float32Array(STAR_COUNT);
    for (let i = 0; i < STAR_COUNT; i++) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.random() * Math.PI * 0.4;
      const r = 150 + Math.random() * 50;
      positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
      positions[i * 3 + 1] = r * Math.cos(phi);
      positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
      sizes[i] = 0.5 + Math.random() * 1.5;
    }
    const geo = new BufferGeometry();
    geo.setAttribute('position', new BufferAttribute(positions, 3));
    geo.setAttribute('size', new BufferAttribute(sizes, 1));
    const mat = new PointsMaterial({
      color: 0xffffff,
      size: 0.8,
      transparent: true,
      opacity: 0.8,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    this.starPoints = new Points(geo, mat);
    this.world.createTransformEntity(this.starPoints);
  }

  private buildLighting() {
    const ambient = new AmbientLight(0x112244, 0.3);
    this.world.createTransformEntity(ambient);

    // Lightning flash light (starts invisible)
    this.lightningFlash = new AmbientLight(0xccddff, 0);
    this.world.createTransformEntity(this.lightningFlash);
  }

  private buildMoon() {
    const moonGroup = new Group();

    // Moon disc
    const moonMat = new MeshBasicMaterial({
      color: 0xeeeedd,
      transparent: true,
      opacity: 0.9,
    });
    const moonGeo = new SphereGeometry(5, 16, 16);
    this.moonMesh = new Mesh(moonGeo, moonMat);
    moonGroup.add(this.moonMesh);

    // Moon glow
    const glowMat = new MeshBasicMaterial({
      color: 0xaabbcc,
      transparent: true,
      opacity: 0.15,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    const glowGeo = new SphereGeometry(8, 16, 16);
    const glowMesh = new Mesh(glowGeo, glowMat);
    moonGroup.add(glowMesh);

    const entity = this.world.createTransformEntity(moonGroup);
    entity.object3D!.position.set(80, 100, -120);
  }

  private buildClouds() {
    const cloudMat = new MeshBasicMaterial({
      color: 0x223344,
      transparent: true,
      opacity: 0.2,
      depthWrite: false,
    });

    const cloudPositions = [
      new Vector3(-40, 60, -80),
      new Vector3(30, 65, -90),
      new Vector3(-60, 55, -70),
      new Vector3(50, 70, -100),
      new Vector3(0, 62, -85),
    ];

    for (const pos of cloudPositions) {
      const cloudGroup = new Group();
      const numBlobs = 3 + Math.floor(Math.random() * 3);
      for (let b = 0; b < numBlobs; b++) {
        const blobGeo = new SphereGeometry(
          4 + Math.random() * 6,
          8,
          6,
        );
        const blob = new Mesh(blobGeo, cloudMat);
        blob.position.set(
          (Math.random() - 0.5) * 12,
          (Math.random() - 0.5) * 2,
          (Math.random() - 0.5) * 4,
        );
        blob.scale.set(1, 0.4, 0.8);
        cloudGroup.add(blob);
      }
      const entity = this.world.createTransformEntity(cloudGroup);
      entity.object3D!.position.copy(pos);
      this.cloudMeshes.push(cloudGroup as unknown as Mesh);
    }
  }

  private buildRainSystem() {
    this.rainPositions = new Float32Array(RAIN_COUNT * 3);
    for (let i = 0; i < RAIN_COUNT; i++) {
      this.rainPositions[i * 3] = (Math.random() - 0.5) * 100;
      this.rainPositions[i * 3 + 1] = Math.random() * 50 + 10;
      this.rainPositions[i * 3 + 2] = (Math.random() - 0.5) * 100;
    }
    const geo = new BufferGeometry();
    geo.setAttribute('position', new Float32BufferAttribute(this.rainPositions, 3));
    const mat = new PointsMaterial({
      color: 0x8899bb,
      size: 0.15,
      transparent: true,
      opacity: 0,
      depthWrite: false,
    });
    this.rainPoints = new Points(geo, mat);
    this.world.createTransformEntity(this.rainPoints);
  }

  private buildBuoys() {
    const buoyPositions = [
      new Vector3(-10, 0, -15),
      new Vector3(15, 0, -18),
      new Vector3(-5, 0, -30),
      new Vector3(22, 0, -10),
      new Vector3(-18, 0, -8),
      new Vector3(5, 0, -22),
    ];

    const buoyBodyMat = new MeshStandardMaterial({ color: 0xff4422, roughness: 0.6 });
    const buoyBandMat = new MeshStandardMaterial({ color: 0xffcc00 });

    for (const pos of buoyPositions) {
      const buoyGroup = new Group();

      // Buoy body
      const bodyGeo = new CylinderGeometry(0.3, 0.4, 1.0, 8);
      const body = new Mesh(bodyGeo, buoyBodyMat);
      body.position.set(0, 0.5, 0);
      buoyGroup.add(body);

      // Yellow band
      const bandGeo = new CylinderGeometry(0.35, 0.35, 0.2, 8);
      const band = new Mesh(bandGeo, buoyBandMat);
      band.position.set(0, 0.7, 0);
      buoyGroup.add(band);

      // Top light
      const topGeo = new SphereGeometry(0.12, 6, 6);
      const topMat = new MeshBasicMaterial({ color: 0xffff00 });
      const top = new Mesh(topGeo, topMat);
      top.position.set(0, 1.1, 0);
      buoyGroup.add(top);

      const buoyLight = new PointLight(0xffff00, 0.5, 10);
      buoyLight.position.set(0, 1.1, 0);
      buoyGroup.add(buoyLight);
      this.buoyLights.push(buoyLight);

      const entity = this.world.createTransformEntity(buoyGroup);
      entity.object3D!.position.copy(pos);
      this.buoyGroups.push(buoyGroup);
    }
  }

  setFogDensity(density: number) {
    this.targetFogDensity = density;
  }

  setSkyColor(r: number, g: number, b: number) {
    this.targetSkyColor.setRGB(r, g, b);
  }

  setRainActive(active: boolean) {
    this.rainActive = active;
  }

  setWindStrength(strength: number) {
    this.targetWindStrength = strength;
  }

  triggerLightning() {
    this.lightningActive = true;
    this.lightningTimer = 0.15 + Math.random() * 0.1;
    this.lightningFlash.intensity = 3 + Math.random() * 2;
  }

  toggleBuoys() {
    this.buoysVisible = !this.buoysVisible;
    for (const group of this.buoyGroups) {
      group.visible = this.buoysVisible;
    }
  }

  areBuoysVisible(): boolean {
    return this.buoysVisible;
  }

  getWindStrength(): number {
    return this.windStrength;
  }

  private buildHorizonGlow() {
    // Atmospheric glow band at the waterline
    const glowGeo = new CylinderGeometry(95, 95, 3, 32, 1, true);
    const glowMat = new MeshBasicMaterial({
      color: 0xff8833,
      transparent: true,
      opacity: 0.04,
      blending: AdditiveBlending,
      depthWrite: false,
      side: DoubleSide,
    });
    this.horizonGlowMesh = new Mesh(glowGeo, glowMat);
    const entity = this.world.createTransformEntity(this.horizonGlowMesh);
    entity.object3D!.position.set(0, 0.5, 0);
  }

  update(delta: number, time: number) {
    // Animate ocean shader
    const mat = this.oceanMesh.material as ShaderMaterial;
    mat.uniforms.uTime.value = time;

    // Wind strength interpolation
    this.windStrength += (this.targetWindStrength - this.windStrength) * delta * 2;
    mat.uniforms.uWindStrength.value = this.windStrength;

    // Animate fog
    if (this.world.scene.fog instanceof FogExp2) {
      const fog = this.world.scene.fog;
      fog.density += (this.targetFogDensity - fog.density) * delta * 2;
    }

    // Pulse harbor lights
    for (const light of this.harborLights) {
      light.intensity = 0.8 + Math.sin(time * 2) * 0.4;
    }

    // Pulse and rotate lantern
    this.lanternLight.intensity = 2.5 + Math.sin(time * 3) * 0.5;
    this.lanternMesh.rotation.y = time * 0.5;

    // Twinkle stars
    const starMat = this.starPoints.material as PointsMaterial;
    starMat.opacity = 0.6 + Math.sin(time * 0.5) * 0.2;

    // Animate rock foam
    for (const foam of this.foamMeshes) {
      const fMat = foam.material as MeshBasicMaterial;
      fMat.opacity = 0.15 + Math.sin(time * 1.5 + foam.id * 0.7) * 0.1;
      foam.scale.setScalar(1.0 + Math.sin(time * 0.8 + foam.id) * 0.1);
    }

    // Rain animation
    const rainMat = this.rainPoints.material as PointsMaterial;
    if (this.rainActive) {
      rainMat.opacity = Math.min(rainMat.opacity + delta * 2, 0.5);
      const posArr = this.rainPositions;
      for (let i = 0; i < RAIN_COUNT; i++) {
        posArr[i * 3 + 1] -= delta * 30;
        posArr[i * 3] += this.windStrength * delta * 5;
        if (posArr[i * 3 + 1] < -1) {
          posArr[i * 3] = (Math.random() - 0.5) * 100;
          posArr[i * 3 + 1] = 40 + Math.random() * 20;
          posArr[i * 3 + 2] = (Math.random() - 0.5) * 100;
        }
      }
      (this.rainPoints.geometry.getAttribute('position') as BufferAttribute).needsUpdate = true;
    } else {
      rainMat.opacity = Math.max(rainMat.opacity - delta, 0);
    }

    // Lightning decay
    if (this.lightningActive) {
      this.lightningTimer -= delta;
      if (this.lightningTimer <= 0) {
        this.lightningActive = false;
        this.lightningFlash.intensity = 0;
      }
    }

    // Sky color lerp
    this.currentSkyColor.lerp(this.targetSkyColor, delta * 1.5);
    if (this.world.scene.fog instanceof FogExp2) {
      this.world.scene.fog.color.copy(this.currentSkyColor);
    }

    // Buoy bobbing and flashing
    for (let i = 0; i < this.buoyGroups.length; i++) {
      const group = this.buoyGroups[i];
      group.position.y = Math.sin(time * 1.2 + i * 1.5) * 0.3;
      this.buoyLights[i].intensity = 0.3 + Math.abs(Math.sin(time * 2 + i * 0.8)) * 0.7;
    }

    // Slow cloud drift
    for (const cloud of this.cloudMeshes) {
      cloud.position.x += delta * 0.5;
      if (cloud.position.x > 100) cloud.position.x = -100;
    }

    // Horizon glow pulse
    const horizonMat = this.horizonGlowMesh.material as MeshBasicMaterial;
    horizonMat.opacity = 0.025 + Math.sin(time * 0.3) * 0.015;
  }
}

import {
  createSystem,
  Vector3,
  Vector2,
  Mesh,
  ConeGeometry,
  MeshBasicMaterial,
  Raycaster,
  SpotLight,
  AdditiveBlending,
  Group,
  InputComponent,
  SphereGeometry,
  PointLight,
} from '@iwsdk/core';

const BEAM_LENGTH = 60;
const BEAM_RADIUS = 4;
const BEAM_ORIGIN = new Vector3(0, 11, 0);

export class LighthouseSystem extends createSystem({}) {
  private beamGroup!: Group;
  private beamMesh!: Mesh;
  private spotLight!: SpotLight;
  private beamDirection = new Vector3(0, 0, -1);
  private beamActive = true;
  private aimTarget = new Vector3(0, 0, -30);
  private raycaster = new Raycaster();

  // Mouse aim for browser mode
  private mouseNDC = new Vector2(0, 0);
  private mouseDown = false;

  // Beam energy system
  private beamEnergy = 100;
  private maxEnergy = 100;
  private energyDrainRate = 8; // per second when active
  private energyRechargeRate = 12; // per second when inactive
  private beamOverheated = false;
  private overheatCooldown = 0;

  // Beam upgrades
  private beamRangeMultiplier = 1.0;
  private beamWidthMultiplier = 1.0;
  private beamIntensityMultiplier = 1.0;

  // Beam tip glow
  private beamTipGlow!: PointLight;
  private beamTipMesh!: Mesh;

  // Exposed for other systems to read beam direction
  public getBeamDirection(): Vector3 {
    return this.beamDirection.clone();
  }

  public getBeamOrigin(): Vector3 {
    return BEAM_ORIGIN.clone();
  }

  public isBeamActive(): boolean {
    return this.beamActive && !this.beamOverheated;
  }

  public getBeamConeAngle(): number {
    return 0.18 * this.beamWidthMultiplier;
  }

  public getBeamEnergy(): number {
    return this.beamEnergy;
  }

  public getMaxEnergy(): number {
    return this.maxEnergy;
  }

  public isOverheated(): boolean {
    return this.beamOverheated;
  }

  // Upgrade methods
  public upgradeRange() {
    this.beamRangeMultiplier = Math.min(this.beamRangeMultiplier + 0.15, 1.6);
  }

  public upgradeWidth() {
    this.beamWidthMultiplier = Math.min(this.beamWidthMultiplier + 0.12, 1.5);
  }

  public upgradeIntensity() {
    this.beamIntensityMultiplier = Math.min(this.beamIntensityMultiplier + 0.2, 2.0);
  }

  public upgradeCapacity() {
    this.maxEnergy = Math.min(this.maxEnergy + 20, 200);
    this.beamEnergy = this.maxEnergy;
  }

  public resetEnergy() {
    this.beamEnergy = this.maxEnergy;
    this.beamOverheated = false;
    this.overheatCooldown = 0;
  }

  init() {
    this.buildBeam();
    this.setupMouseControls();
  }

  private buildBeam() {
    this.beamGroup = new Group();

    // Volumetric beam cone
    const beamGeo = new ConeGeometry(BEAM_RADIUS, BEAM_LENGTH, 16, 1, true);
    beamGeo.translate(0, -BEAM_LENGTH / 2, 0);
    const beamMat = new MeshBasicMaterial({
      color: 0xffcc44,
      transparent: true,
      opacity: 0.08,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    this.beamMesh = new Mesh(beamGeo, beamMat);
    this.beamGroup.add(this.beamMesh);

    // Spot light for actual illumination
    this.spotLight = new SpotLight(0xffcc44, 5, BEAM_LENGTH, 0.2, 0.5);
    this.spotLight.position.set(0, 0, 0);
    this.beamGroup.add(this.spotLight);
    this.beamGroup.add(this.spotLight.target);

    // Beam tip glow — bright point at the end of the beam where it hits water
    const tipGlowMat = new MeshBasicMaterial({
      color: 0xffee66,
      transparent: true,
      opacity: 0.4,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    const tipGlowGeo = new SphereGeometry(2, 8, 8);
    this.beamTipMesh = new Mesh(tipGlowGeo, tipGlowMat);
    this.beamTipMesh.position.set(0, -BEAM_LENGTH, 0);
    this.beamGroup.add(this.beamTipMesh);

    this.beamTipGlow = new PointLight(0xffcc44, 3, 15);
    this.beamTipGlow.position.set(0, -BEAM_LENGTH, 0);
    this.beamGroup.add(this.beamTipGlow);

    const entity = this.world.createTransformEntity(this.beamGroup);
    entity.object3D!.position.copy(BEAM_ORIGIN);
  }

  private setupMouseControls() {
    const canvas = this.world.renderer.domElement;
    canvas.addEventListener('mousemove', (e: MouseEvent) => {
      this.mouseNDC.set(
        (e.clientX / window.innerWidth) * 2 - 1,
        -(e.clientY / window.innerHeight) * 2 + 1,
      );
    });
    canvas.addEventListener('mousedown', () => {
      this.mouseDown = true;
    });
    canvas.addEventListener('mouseup', () => {
      this.mouseDown = false;
    });
    canvas.addEventListener('click', () => {
      this.beamActive = !this.beamActive;
    });
  }

  setBeamActive(active: boolean) {
    this.beamActive = active;
  }

  toggleBeam() {
    this.beamActive = !this.beamActive;
  }

  update(delta: number, time: number) {
    this.updateBeamEnergy(delta);
    this.handleXRInput();
    this.handleBrowserInput();
    this.updateBeamVisuals(time);
  }

  private updateBeamEnergy(delta: number) {
    if (this.beamOverheated) {
      this.overheatCooldown -= delta;
      if (this.overheatCooldown <= 0) {
        this.beamOverheated = false;
        this.beamEnergy = this.maxEnergy * 0.3;
      }
      return;
    }

    if (this.beamActive) {
      this.beamEnergy -= this.energyDrainRate * delta;
      if (this.beamEnergy <= 0) {
        this.beamEnergy = 0;
        this.beamOverheated = true;
        this.overheatCooldown = 2.0;
      }
    } else {
      this.beamEnergy = Math.min(this.beamEnergy + this.energyRechargeRate * delta, this.maxEnergy);
    }
  }

  private handleXRInput() {
    const rightPad = this.world.input.xr.gamepads.right;
    if (!rightPad) return;

    // Toggle beam with trigger
    if (rightPad.getButtonDown(InputComponent.Trigger)) {
      this.beamActive = !this.beamActive;
    }

    // Use ray space for beam direction
    const raySpace = this.world.player.raySpaces.right;
    if (raySpace) {
      const worldPos = new Vector3();
      const worldDir = new Vector3(0, 0, -1);
      raySpace.getWorldPosition(worldPos);
      raySpace.getWorldDirection(worldDir);

      // Aim beam in ray direction projected from lighthouse top
      this.beamDirection.copy(worldDir).normalize();
    }
  }

  private handleBrowserInput() {
    // In browser mode, use mouse position to aim beam
    if (this.world.input.xr.gamepads.right) return; // XR mode active

    // Project mouse into world to determine beam direction
    this.raycaster.setFromCamera(
      this.mouseNDC,
      this.world.camera,
    );

    // Intersect with ocean plane (y=0)
    const planeY = 0;
    const origin = this.raycaster.ray.origin;
    const direction = this.raycaster.ray.direction;
    if (direction.y !== 0) {
      const t = (planeY - origin.y) / direction.y;
      if (t > 0) {
        this.aimTarget.set(
          origin.x + direction.x * t,
          planeY,
          origin.z + direction.z * t,
        );
        this.beamDirection
          .copy(this.aimTarget)
          .sub(BEAM_ORIGIN)
          .normalize();
      }
    }
  }

  private updateBeamVisuals(time: number) {
    const mat = this.beamMesh.material as MeshBasicMaterial;
    const effectiveActive = this.beamActive && !this.beamOverheated;

    if (effectiveActive) {
      // Energy-based opacity — dimmer as energy drops
      const energyFrac = this.beamEnergy / this.maxEnergy;
      const baseOpacity = 0.04 + energyFrac * 0.06;
      mat.opacity = baseOpacity + Math.sin(time * 4) * 0.015;
      this.spotLight.intensity = (3 + Math.sin(time * 3) * 1) * this.beamIntensityMultiplier * energyFrac;

      // Orient beam group to point in beam direction
      const target = BEAM_ORIGIN.clone().add(
        this.beamDirection.clone().multiplyScalar(BEAM_LENGTH * this.beamRangeMultiplier),
      );
      this.beamGroup.lookAt(target);
      this.beamGroup.rotateX(Math.PI / 2); // Cone points along -Y, need to fix

      // Move spotlight target
      this.spotLight.target.position
        .copy(this.beamDirection)
        .multiplyScalar(BEAM_LENGTH * this.beamRangeMultiplier);

      // Beam tip glow — pulse at water intersection
      const tipMat = this.beamTipMesh.material as MeshBasicMaterial;
      tipMat.opacity = 0.2 + Math.sin(time * 5) * 0.15;
      this.beamTipGlow.intensity = (2 + Math.sin(time * 4) * 1) * energyFrac;
      this.beamTipMesh.scale.setScalar(0.8 + Math.sin(time * 3) * 0.2);

      // Overheat warning flicker
      if (energyFrac < 0.2) {
        const flicker = Math.sin(time * 15) > 0 ? 0.5 : 1.0;
        mat.opacity *= flicker;
        this.spotLight.intensity *= flicker;
      }
    } else {
      mat.opacity = 0;
      this.spotLight.intensity = 0;

      // Dim the tip glow
      const tipMat = this.beamTipMesh.material as MeshBasicMaterial;
      tipMat.opacity = 0;
      this.beamTipGlow.intensity = 0;
    }

    // Overheat red pulse on beam mesh
    if (this.beamOverheated) {
      mat.color.setHex(0xff4422);
      mat.opacity = Math.abs(Math.sin(time * 8)) * 0.03;
    } else {
      mat.color.setHex(0xffcc44);
    }
  }
}

import {
  createSystem,
  Vector3,
  Mesh,
  BoxGeometry,
  MeshStandardMaterial,
  CylinderGeometry,
  SphereGeometry,
  MeshBasicMaterial,
  PointLight,
  Group,
  BufferGeometry,
  BufferAttribute,
  Points,
  PointsMaterial,
  AdditiveBlending,
} from '@iwsdk/core';
import { Ship } from './components.js';
import { LighthouseSystem } from './lighthouse-system.js';
import { EnvironmentSystem } from './environment-system.js';
import { AudioSystem } from './audio-system.js';

// Ship types: 0=fishing, 1=cargo, 2=ferry, 3=emergency, 4=treasure
export interface ShipData {
  entity: ReturnType<typeof createSystem.prototype.world.createTransformEntity>;
  group: Group;
  speed: number;
  heading: number;
  isLit: boolean;
  litTimer: number;
  docked: boolean;
  sinking: boolean;
  sinkProgress: number;
  spawnAngle: number;
  portLight: PointLight;
  starboardLight: PointLight;
  shipType: number;
  points: number;
  wakeEntity: ReturnType<typeof createSystem.prototype.world.createTransformEntity>;
  wakePoints: Points;
  wakePositions: Float32Array;
  wakeIdx: number;
  // New: illumination glow
  glowLight: PointLight;
  // New: distress flare state
  flareTimer: number;
  nearRockTimer: number;
}

interface FlareData {
  entity: ReturnType<typeof createSystem.prototype.world.createTransformEntity>;
  points: Points;
  life: number;
  posArr: Float32Array;
  velArr: Float32Array;
}

const HARBOR_POS = new Vector3(8, 0, -5);
const DOCK_RADIUS = 4;
const SPAWN_DISTANCE = 55;
const BEAM_HIT_RADIUS = 6;
const WAKE_PARTICLE_COUNT = 30;
const FLARE_PARTICLE_COUNT = 15;

// Ship type configs (extended with emergency and treasure)
const SHIP_CONFIGS = [
  { name: 'fishing', hullColor: 0x446688, cabinColor: 0x667799, scale: 0.8, speedMod: 1.2, points: 50, hullW: 0.8, hullH: 0.4, hullD: 2.0 },
  { name: 'cargo', hullColor: 0x554433, cabinColor: 0x665544, scale: 1.3, speedMod: 0.7, points: 150, hullW: 1.8, hullH: 0.7, hullD: 4.0 },
  { name: 'ferry', hullColor: 0xccccdd, cabinColor: 0xddddee, scale: 1.1, speedMod: 0.9, points: 200, hullW: 1.4, hullH: 0.5, hullD: 3.2 },
  { name: 'emergency', hullColor: 0xcc2222, cabinColor: 0xff4444, scale: 0.9, speedMod: 1.5, points: 300, hullW: 1.0, hullH: 0.4, hullD: 2.5 },
  { name: 'treasure', hullColor: 0xaa8822, cabinColor: 0xffcc44, scale: 1.2, speedMod: 0.5, points: 500, hullW: 1.6, hullH: 0.6, hullD: 3.5 },
];

export class ShipSystem extends createSystem({}) {
  private ships: ShipData[] = [];
  private lighthouseSystem!: LighthouseSystem;
  private envSystem!: EnvironmentSystem;
  private audioSystem!: AudioSystem;
  private tempVec = new Vector3();
  private tempVec2 = new Vector3();

  // Game state (managed by GameSystem)
  public shipsToSpawn = 0;
  public spawnTimer = 0;
  public spawnInterval = 3;
  public baseSpeed = 0.8;
  public waveShipCount = 0;

  // Splash particle pool
  private splashPool: { entity: ReturnType<typeof createSystem.prototype.world.createTransformEntity>; points: Points; life: number; posArr: Float32Array; velArr: Float32Array }[] = [];

  // Distress flare pool
  private flarePool: FlareData[] = [];

  init() {
    this.lighthouseSystem = this.world.getSystem(LighthouseSystem)!;
    this.envSystem = this.world.getSystem(EnvironmentSystem)!;
    this.audioSystem = this.world.getSystem(AudioSystem)!;
  }

  private pickShipType(): number {
    const r = Math.random();
    if (r < 0.5) return 0;       // 50% fishing
    if (r < 0.85) return 1;      // 35% cargo
    return 2;                    // 15% ferry
  }

  spawnShip(forceType?: number): ShipData {
    const shipType = forceType !== undefined ? forceType : this.pickShipType();
    const cfg = SHIP_CONFIGS[shipType];
    const group = new Group();

    // Hull
    const hullMat = new MeshStandardMaterial({ color: cfg.hullColor, roughness: 0.7 });
    const hullGeo = new BoxGeometry(cfg.hullW, cfg.hullH, cfg.hullD);
    const hull = new Mesh(hullGeo, hullMat);
    hull.position.y = 0.1;
    group.add(hull);

    // Cabin
    const cabinMat = new MeshStandardMaterial({ color: cfg.cabinColor, roughness: 0.6 });
    const cabinH = shipType === 2 ? 0.9 : shipType === 4 ? 0.8 : 0.6;
    const cabinGeo = new BoxGeometry(cfg.hullW * 0.6, cabinH, cfg.hullD * 0.35);
    const cabin = new Mesh(cabinGeo, cabinMat);
    cabin.position.set(0, 0.1 + cfg.hullH / 2 + cabinH / 2, -cfg.hullD * 0.1);
    group.add(cabin);

    // Mast (fishing boats have taller mast)
    const mastMat = new MeshStandardMaterial({ color: 0x888888 });
    const mastH = shipType === 0 ? 2.0 : 1.2;
    const mastGeo = new CylinderGeometry(0.04, 0.04, mastH, 4);
    const mast = new Mesh(mastGeo, mastMat);
    mast.position.set(0, 0.1 + cfg.hullH / 2 + mastH / 2, cfg.hullD * 0.2);
    group.add(mast);

    // Cargo containers (cargo ships only)
    if (shipType === 1) {
      const containerMat = new MeshStandardMaterial({ color: 0xcc6622, roughness: 0.8 });
      for (let c = 0; c < 3; c++) {
        const contGeo = new BoxGeometry(0.5, 0.4, 0.6);
        const cont = new Mesh(contGeo, containerMat);
        cont.position.set(
          (c - 1) * 0.55,
          0.1 + cfg.hullH / 2 + 0.2,
          cfg.hullD * 0.25,
        );
        group.add(cont);
      }
    }

    // Ferry windows (ferry only)
    if (shipType === 2) {
      const windowMat = new MeshBasicMaterial({ color: 0xffdd88 });
      for (let w = 0; w < 4; w++) {
        const winGeo = new BoxGeometry(0.02, 0.15, 0.15);
        const winMesh = new Mesh(winGeo, windowMat);
        winMesh.position.set(
          cfg.hullW * 0.3 + 0.01,
          0.1 + cfg.hullH / 2 + 0.3,
          -cfg.hullD * 0.15 + w * 0.25,
        );
        group.add(winMesh);

        const winMesh2 = winMesh.clone();
        winMesh2.position.x = -(cfg.hullW * 0.3 + 0.01);
        group.add(winMesh2);
      }
    }

    // Emergency ship: flashing red light on top
    if (shipType === 3) {
      const emergencyGlowMat = new MeshBasicMaterial({ color: 0xff0000 });
      const emergencyGlowGeo = new SphereGeometry(0.15, 6, 6);
      const emergencyGlow = new Mesh(emergencyGlowGeo, emergencyGlowMat);
      emergencyGlow.position.set(0, 0.1 + cfg.hullH + 1.0, 0);
      group.add(emergencyGlow);

      const redLight = new PointLight(0xff0000, 2, 8);
      redLight.position.copy(emergencyGlow.position);
      group.add(redLight);
    }

    // Treasure ship: gold accents and glow
    if (shipType === 4) {
      const goldMat = new MeshBasicMaterial({ color: 0xffcc00, transparent: true, opacity: 0.8 });
      const goldRimGeo = new CylinderGeometry(cfg.hullW * 0.55, cfg.hullW * 0.55, 0.1, 8);
      const goldRim = new Mesh(goldRimGeo, goldMat);
      goldRim.position.set(0, 0.1 + cfg.hullH + 0.05, 0);
      group.add(goldRim);

      // Treasure glow
      const treasureLight = new PointLight(0xffaa00, 2, 10);
      treasureLight.position.set(0, 0.5, 0);
      group.add(treasureLight);
    }

    // Navigation lights
    const portLightGeo = new SphereGeometry(0.08, 6, 6);
    const portLightMat = new MeshBasicMaterial({ color: 0xff2222 });
    const portLightMesh = new Mesh(portLightGeo, portLightMat);
    portLightMesh.position.set(-cfg.hullW / 2 - 0.1, 0.3, cfg.hullD / 2);
    group.add(portLightMesh);
    const portLight = new PointLight(0xff2222, 0.8, 5);
    portLight.position.copy(portLightMesh.position);
    group.add(portLight);

    const starLightGeo = new SphereGeometry(0.08, 6, 6);
    const starLightMat = new MeshBasicMaterial({ color: 0x22ff22 });
    const starLightMesh = new Mesh(starLightGeo, starLightMat);
    starLightMesh.position.set(cfg.hullW / 2 + 0.1, 0.3, cfg.hullD / 2);
    group.add(starLightMesh);
    const starboardLight = new PointLight(0x22ff22, 0.8, 5);
    starboardLight.position.copy(starLightMesh.position);
    group.add(starboardLight);

    // Illumination glow light (hidden until beam hits ship)
    const glowLight = new PointLight(0xffcc44, 0, 8);
    glowLight.position.set(0, 0.5, 0);
    group.add(glowLight);

    // Scale the whole ship
    group.scale.setScalar(cfg.scale);

    // Spawn position
    const spawnAngle = Math.random() * Math.PI * 2;
    const spawnX = Math.cos(spawnAngle) * SPAWN_DISTANCE;
    const spawnZ = Math.sin(spawnAngle) * SPAWN_DISTANCE;

    const entity = this.world.createTransformEntity(group);
    entity.object3D!.position.set(spawnX, 0, spawnZ);

    const headingToCenter = Math.atan2(-spawnZ, -spawnX);

    // Wake trail particles
    const wakePositions = new Float32Array(WAKE_PARTICLE_COUNT * 3);
    for (let i = 0; i < WAKE_PARTICLE_COUNT * 3; i++) {
      wakePositions[i] = 0;
    }
    const wakeGeo = new BufferGeometry();
    wakeGeo.setAttribute('position', new BufferAttribute(wakePositions, 3));
    const wakeMat = new PointsMaterial({
      color: 0x88ccdd,
      size: 0.3,
      transparent: true,
      opacity: 0.3,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    const wakePoints = new Points(wakeGeo, wakeMat);
    const wakeEntity = this.world.createTransformEntity(wakePoints);

    const shipData: ShipData = {
      entity,
      group,
      speed: this.baseSpeed * cfg.speedMod + Math.random() * 0.2,
      heading: headingToCenter,
      isLit: false,
      litTimer: 0,
      docked: false,
      sinking: false,
      sinkProgress: 0,
      spawnAngle,
      portLight,
      starboardLight,
      shipType,
      points: cfg.points,
      wakeEntity,
      wakePoints,
      wakePositions,
      wakeIdx: 0,
      glowLight,
      flareTimer: 0,
      nearRockTimer: 0,
    };

    this.ships.push(shipData);
    this.audioSystem?.playShipBell();

    // Special spawn sounds
    if (shipType === 3) {
      this.audioSystem?.playDistressHorn();
    } else if (shipType === 4) {
      this.audioSystem?.playTreasureChime();
    }

    return shipData;
  }

  getActiveShipCount(): number {
    return this.ships.filter((s) => !s.docked && !s.sinking).length;
  }

  getAllShips(): ShipData[] {
    return this.ships;
  }

  getShipCountByType(): [number, number, number] {
    let f = 0, c = 0, p = 0;
    for (const s of this.ships) {
      if (s.docked || s.sinking) continue;
      if (s.shipType === 0) f++;
      else if (s.shipType === 1) c++;
      else p++;
    }
    return [f, c, p];
  }

  getSpecialShipCount(): [number, number] {
    let emergency = 0, treasure = 0;
    for (const s of this.ships) {
      if (s.docked || s.sinking) continue;
      if (s.shipType === 3) emergency++;
      if (s.shipType === 4) treasure++;
    }
    return [emergency, treasure];
  }

  clearAllShips() {
    for (const ship of this.ships) {
      ship.entity.dispose();
      ship.wakeEntity.dispose();
    }
    this.ships = [];

    // Clear flares
    for (const flare of this.flarePool) {
      flare.entity.dispose();
    }
    this.flarePool = [];
  }

  private spawnSplash(position: Vector3) {
    const count = 20;
    const posArr = new Float32Array(count * 3);
    const velArr = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      posArr[i * 3] = position.x + (Math.random() - 0.5) * 1.5;
      posArr[i * 3 + 1] = position.y + Math.random() * 0.5;
      posArr[i * 3 + 2] = position.z + (Math.random() - 0.5) * 1.5;
      velArr[i * 3] = (Math.random() - 0.5) * 3;
      velArr[i * 3 + 1] = 2 + Math.random() * 3;
      velArr[i * 3 + 2] = (Math.random() - 0.5) * 3;
    }
    const geo = new BufferGeometry();
    geo.setAttribute('position', new BufferAttribute(posArr, 3));
    const mat = new PointsMaterial({
      color: 0xaaddee,
      size: 0.25,
      transparent: true,
      opacity: 0.7,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    const points = new Points(geo, mat);
    const entity = this.world.createTransformEntity(points);
    this.splashPool.push({ entity, points, life: 1.0, posArr, velArr });
  }

  private spawnDistressFlare(position: Vector3) {
    const posArr = new Float32Array(FLARE_PARTICLE_COUNT * 3);
    const velArr = new Float32Array(FLARE_PARTICLE_COUNT * 3);
    for (let i = 0; i < FLARE_PARTICLE_COUNT; i++) {
      posArr[i * 3] = position.x;
      posArr[i * 3 + 1] = position.y + 0.5;
      posArr[i * 3 + 2] = position.z;
      const angle = Math.random() * Math.PI * 2;
      const upSpeed = 5 + Math.random() * 5;
      velArr[i * 3] = Math.cos(angle) * (0.5 + Math.random());
      velArr[i * 3 + 1] = upSpeed;
      velArr[i * 3 + 2] = Math.sin(angle) * (0.5 + Math.random());
    }
    const geo = new BufferGeometry();
    geo.setAttribute('position', new BufferAttribute(posArr, 3));
    const mat = new PointsMaterial({
      color: 0xff3322,
      size: 0.5,
      transparent: true,
      opacity: 0.9,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    const points = new Points(geo, mat);
    const entity = this.world.createTransformEntity(points);
    this.flarePool.push({ entity, points, life: 2.5, posArr, velArr });
  }

  update(delta: number, time: number) {
    // Spawn queued ships
    if (this.shipsToSpawn > 0) {
      this.spawnTimer -= delta;
      if (this.spawnTimer <= 0) {
        this.spawnShip();
        this.shipsToSpawn--;
        this.spawnTimer = this.spawnInterval;
      }
    }

    const beamOrigin = this.lighthouseSystem.getBeamOrigin();
    const beamDir = this.lighthouseSystem.getBeamDirection();
    const beamActive = this.lighthouseSystem.isBeamActive();
    const beamConeAngle = this.lighthouseSystem.getBeamConeAngle();
    const rockPositions = this.envSystem.rockPositions;
    const windStrength = this.envSystem.getWindStrength();

    for (let i = this.ships.length - 1; i >= 0; i--) {
      const ship = this.ships[i];
      if (ship.docked) continue;

      const pos = ship.entity.object3D!.position;

      // Handle sinking
      if (ship.sinking) {
        ship.sinkProgress += delta * 0.5;
        pos.y = -ship.sinkProgress * 3;
        ship.entity.object3D!.rotation.z = Math.sin(time * 5) * ship.sinkProgress * 0.5;
        if (ship.sinkProgress >= 1) {
          ship.entity.dispose();
          ship.wakeEntity.dispose();
          this.ships.splice(i, 1);
        }
        continue;
      }

      // Check if lit by beam
      if (beamActive) {
        this.tempVec.copy(pos).sub(beamOrigin);
        const dot = this.tempVec.dot(beamDir);
        if (dot > 0) {
          this.tempVec2.copy(beamDir).multiplyScalar(dot);
          const perpDist = this.tempVec.sub(this.tempVec2).length();
          const beamWidthAtDist = dot * beamConeAngle;
          ship.isLit = perpDist < beamWidthAtDist + BEAM_HIT_RADIUS;
        } else {
          ship.isLit = false;
        }
      } else {
        ship.isLit = false;
      }

      // Update lit timer
      if (ship.isLit) {
        ship.litTimer = Math.min(ship.litTimer + delta, 2.0);
      } else {
        ship.litTimer = Math.max(ship.litTimer - delta * 0.5, 0);
      }

      // Illumination glow — ships glow when lit
      const glowTarget = ship.isLit ? 3.0 : 0;
      ship.glowLight.intensity += (glowTarget - ship.glowLight.intensity) * delta * 5;

      // Navigation
      if (ship.litTimer > 0.3) {
        const toHarbor = this.tempVec.copy(HARBOR_POS).sub(pos).normalize();
        const targetHeading = Math.atan2(toHarbor.x, toHarbor.z);
        let angleDiff = targetHeading - ship.heading;
        while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
        while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
        ship.heading += angleDiff * delta * 2;
      } else {
        ship.heading += (Math.sin(time + i * 3.7) * 0.2) * delta;
      }

      // Wind drift
      ship.heading += windStrength * 0.05 * delta;

      // Move ship
      const moveSpeed = ship.speed * delta;
      pos.x += Math.sin(ship.heading) * moveSpeed;
      pos.z += Math.cos(ship.heading) * moveSpeed;

      // Bob on waves
      pos.y = Math.sin(time * 1.5 + i * 2) * 0.15;

      // Face heading
      ship.entity.object3D!.rotation.y = ship.heading;
      ship.entity.object3D!.rotation.z = Math.sin(time * 2 + i) * 0.05;

      // Pulse navigation lights
      const lightPulse = ship.isLit ? 2.0 : 0.5 + Math.sin(time * 3 + i) * 0.3;
      ship.portLight.intensity = lightPulse;
      ship.starboardLight.intensity = lightPulse;

      // Emergency ship: fast flashing red
      if (ship.shipType === 3) {
        const flash = Math.sin(time * 10) > 0 ? 3.0 : 0.5;
        ship.portLight.intensity = flash;
        ship.starboardLight.intensity = flash;
        ship.portLight.color.setHex(0xff0000);
        ship.starboardLight.color.setHex(0xff0000);
      }

      // Treasure ship: golden pulse
      if (ship.shipType === 4) {
        ship.glowLight.color.setHex(0xffaa00);
        ship.glowLight.intensity = 1.5 + Math.sin(time * 2) * 0.5;
      }

      // Update wake trail
      if (!ship.docked && !ship.sinking) {
        const wIdx = ship.wakeIdx % WAKE_PARTICLE_COUNT;
        ship.wakePositions[wIdx * 3] = pos.x - Math.sin(ship.heading) * 1.5;
        ship.wakePositions[wIdx * 3 + 1] = 0.05;
        ship.wakePositions[wIdx * 3 + 2] = pos.z - Math.cos(ship.heading) * 1.5;
        ship.wakeIdx++;
        (ship.wakePoints.geometry.getAttribute('position') as BufferAttribute).needsUpdate = true;
      }

      // Distress flares — ships near rocks fire flares
      let nearestRockDist = Infinity;
      for (const rockPos of rockPositions) {
        const dist = pos.distanceTo(rockPos);
        if (dist < nearestRockDist) nearestRockDist = dist;
      }
      if (nearestRockDist < 8 && !ship.isLit) {
        ship.nearRockTimer += delta;
        ship.flareTimer -= delta;
        if (ship.flareTimer <= 0 && ship.nearRockTimer > 1.0) {
          this.spawnDistressFlare(pos.clone());
          this.audioSystem?.playFlareSound();
          ship.flareTimer = 3.0 + Math.random() * 2;
        }
      } else {
        ship.nearRockTimer = 0;
      }

      // Check harbor dock
      const distToHarbor = pos.distanceTo(HARBOR_POS);
      if (distToHarbor < DOCK_RADIUS) {
        ship.docked = true;
        this.spawnSplash(pos.clone());
        this.audioSystem?.playDockChime();
        continue;
      }

      // Check rock collisions
      for (const rockPos of rockPositions) {
        const dist = pos.distanceTo(rockPos);
        if (dist < 2.5) {
          ship.sinking = true;
          this.spawnSplash(pos.clone());
          this.audioSystem?.playCrashSound();
          break;
        }
      }

      // Out of bounds
      if (pos.length() > SPAWN_DISTANCE + 10) {
        ship.sinking = true;
      }
    }

    // Update splash particles
    for (let s = this.splashPool.length - 1; s >= 0; s--) {
      const splash = this.splashPool[s];
      splash.life -= delta * 1.5;
      if (splash.life <= 0) {
        splash.entity.dispose();
        this.splashPool.splice(s, 1);
        continue;
      }
      const pMat = splash.points.material as PointsMaterial;
      pMat.opacity = splash.life * 0.7;
      for (let p = 0; p < 20; p++) {
        splash.posArr[p * 3] += splash.velArr[p * 3] * delta;
        splash.posArr[p * 3 + 1] += splash.velArr[p * 3 + 1] * delta;
        splash.posArr[p * 3 + 2] += splash.velArr[p * 3 + 2] * delta;
        splash.velArr[p * 3 + 1] -= 9.8 * delta; // gravity
      }
      (splash.points.geometry.getAttribute('position') as BufferAttribute).needsUpdate = true;
    }

    // Update distress flares
    for (let f = this.flarePool.length - 1; f >= 0; f--) {
      const flare = this.flarePool[f];
      flare.life -= delta;
      if (flare.life <= 0) {
        flare.entity.dispose();
        this.flarePool.splice(f, 1);
        continue;
      }
      const fMat = flare.points.material as PointsMaterial;
      fMat.opacity = Math.min(flare.life, 1.0) * 0.9;
      // Drift with gravity and spread
      for (let p = 0; p < FLARE_PARTICLE_COUNT; p++) {
        flare.posArr[p * 3] += flare.velArr[p * 3] * delta;
        flare.posArr[p * 3 + 1] += flare.velArr[p * 3 + 1] * delta;
        flare.posArr[p * 3 + 2] += flare.velArr[p * 3 + 2] * delta;
        flare.velArr[p * 3 + 1] -= 3.0 * delta; // slow gravity for flares
      }
      (flare.points.geometry.getAttribute('position') as BufferAttribute).needsUpdate = true;
    }
  }
}

import { createSystem, UIKitMLAsset } from '@iwsdk/core';
import { ShipSystem } from './ship-system.js';
import { LighthouseSystem } from './lighthouse-system.js';
import { AudioSystem } from './audio-system.js';
import { EnvironmentSystem } from './environment-system.js';

type GameState = 'menu' | 'tutorial' | 'settings' | 'playing' | 'wave-complete' | 'game-over';

interface WaveConfig {
  shipCount: number;
  spawnInterval: number;
  shipSpeed: number;
  fogDensity: number;
  stormChance: number;
  hasRain: boolean;
  windStrength: number;
  skyShift: [number, number, number];
  emergencyChance: number;
  treasureChance: number;
}

export class GameSystem extends createSystem({}) {
  private state: GameState = 'menu';
  private wave = 0;
  private score = 0;
  private lives = 3;
  private highScore = 0;
  private bestWave = 0;
  private totalShipsSaved = 0;
  private waveShipsSaved = 0;
  private waveShipsLost = 0;
  private waveShipTotal = 0;
  private fogHornTimer = 0;
  private lightningTimer = 0;
  private waveHasStorm = false;
  private waveStartTimer = 0;
  private showingWaveStart = false;

  // Special event timers
  private emergencyTimer = 0;
  private treasureTimer = 0;
  private emergencyChance = 0;
  private treasureChance = 0;
  private emergencySpawned = false;
  private treasureSpawned = false;

  private shipSystem!: ShipSystem;
  private lighthouseSystem!: LighthouseSystem;
  private audioSystem!: AudioSystem;
  private envSystem!: EnvironmentSystem;

  // Panels
  private menuPanel: UIKitMLAsset | undefined = undefined;
  private hudPanel: UIKitMLAsset | undefined = undefined;
  private waveCompletePanel: UIKitMLAsset | undefined = undefined;
  private gameOverPanel: UIKitMLAsset | undefined = undefined;
  private settingsPanel: UIKitMLAsset | undefined = undefined;
  private tutorialPanel: UIKitMLAsset | undefined = undefined;
  private compassPanel: UIKitMLAsset | undefined = undefined;

  init() {
    this.shipSystem = this.world.getSystem(ShipSystem)!;
    this.lighthouseSystem = this.world.getSystem(LighthouseSystem)!;
    this.audioSystem = this.world.getSystem(AudioSystem)!;
    this.envSystem = this.world.getSystem(EnvironmentSystem)!;

    this.highScore = parseInt(localStorage.getItem('neon-lighthouse-high-score') || '0', 10);
    this.bestWave = parseInt(localStorage.getItem('neon-lighthouse-best-wave') || '0', 10);

    this.menuPanel = this.world.getSceneObject<UIKitMLAsset>('menu-panel-node');
    this.hudPanel = this.world.getSceneObject<UIKitMLAsset>('hud-panel-node');
    this.waveCompletePanel = this.world.getSceneObject<UIKitMLAsset>('wave-complete-panel-node');
    this.gameOverPanel = this.world.getSceneObject<UIKitMLAsset>('game-over-panel-node');
    this.settingsPanel = this.world.getSceneObject<UIKitMLAsset>('settings-panel-node');
    this.tutorialPanel = this.world.getSceneObject<UIKitMLAsset>('tutorial-panel-node');
    this.compassPanel = this.world.getSceneObject<UIKitMLAsset>('compass-panel-node');

    this.setupPanelButtons();
    this.showState('menu');
  }

  private setupPanelButtons() {
    // Menu buttons
    this.menuPanel?.getElementById('btn-play')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.startGame();
    });
    this.menuPanel?.getElementById('btn-tutorial')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('tutorial');
    });
    this.menuPanel?.getElementById('btn-settings')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('settings');
    });

    // Tutorial
    this.tutorialPanel?.getElementById('btn-got-it')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('menu');
    });

    // Settings
    this.settingsPanel?.getElementById('btn-sensitivity')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
    });
    this.settingsPanel?.getElementById('btn-volume')?.addEventListener('click', () => {
      this.audioSystem.toggleVolume();
      this.audioSystem.playUIClick();
      this.settingsPanel?.getElementById('volume-val')?.setProperties({
        text: this.audioSystem.isVolumeOn() ? 'ON' : 'OFF',
      });
    });
    this.settingsPanel?.getElementById('btn-buoys')?.addEventListener('click', () => {
      this.envSystem.toggleBuoys();
      this.audioSystem.playUIClick();
      this.settingsPanel?.getElementById('buoy-val')?.setProperties({
        text: this.envSystem.areBuoysVisible() ? 'ON' : 'OFF',
      });
    });
    this.settingsPanel?.getElementById('btn-back')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('menu');
    });

    // Wave complete — next wave and upgrades
    this.waveCompletePanel?.getElementById('btn-next-wave')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.startWave();
    });
    this.waveCompletePanel?.getElementById('btn-upgrade-range')?.addEventListener('click', () => {
      this.tryUpgrade('range');
    });
    this.waveCompletePanel?.getElementById('btn-upgrade-width')?.addEventListener('click', () => {
      this.tryUpgrade('width');
    });
    this.waveCompletePanel?.getElementById('btn-upgrade-energy')?.addEventListener('click', () => {
      this.tryUpgrade('energy');
    });

    // Game over
    this.gameOverPanel?.getElementById('btn-play-again')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.startGame();
    });
    this.gameOverPanel?.getElementById('btn-main-menu')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('menu');
    });
  }

  private tryUpgrade(type: 'range' | 'width' | 'energy') {
    const cost = 300;
    if (this.score < cost) return;
    this.score -= cost;
    this.audioSystem.playUpgradeSound();

    if (type === 'range') {
      this.lighthouseSystem.upgradeRange();
    } else if (type === 'width') {
      this.lighthouseSystem.upgradeWidth();
    } else {
      this.lighthouseSystem.upgradeCapacity();
    }

    this.updateUpgradePanel();
  }

  private updateUpgradePanel() {
    const canAfford = this.score >= 300;
    const affordText = canAfford ? '300 pts' : 'NEED 300';
    this.waveCompletePanel?.getElementById('upgrade-cost')?.setProperties({ text: affordText });
    this.waveCompletePanel?.getElementById('upgrade-score')?.setProperties({ text: String(this.score) });
  }

  private showState(newState: GameState) {
    this.state = newState;
    const panels = [
      { panel: this.menuPanel, show: newState === 'menu' },
      { panel: this.hudPanel, show: newState === 'playing' },
      { panel: this.waveCompletePanel, show: newState === 'wave-complete' },
      { panel: this.gameOverPanel, show: newState === 'game-over' },
      { panel: this.settingsPanel, show: newState === 'settings' },
      { panel: this.tutorialPanel, show: newState === 'tutorial' },
      { panel: this.compassPanel, show: newState === 'playing' },
    ];
    for (const { panel, show } of panels) {
      if (panel) panel.visible = show;
    }
  }

  private startGame() {
    this.score = 0;
    this.lives = 3;
    this.wave = 0;
    this.totalShipsSaved = 0;
    this.shipSystem.clearAllShips();
    this.envSystem.setFogDensity(0.012);
    this.envSystem.setRainActive(false);
    this.envSystem.setWindStrength(0);

    this.menuPanel?.getElementById('high-score')?.setProperties({ text: String(this.highScore) });
    this.menuPanel?.getElementById('best-wave')?.setProperties({ text: String(this.bestWave) });

    this.startWave();
  }

  private startWave() {
    this.wave++;
    this.waveShipsSaved = 0;
    this.waveShipsLost = 0;
    this.emergencySpawned = false;
    this.treasureSpawned = false;
    this.shipSystem.clearAllShips();

    const config = this.getWaveConfig(this.wave);
    this.waveShipTotal = config.shipCount;
    this.shipSystem.shipsToSpawn = config.shipCount;
    this.shipSystem.spawnInterval = config.spawnInterval;
    this.shipSystem.baseSpeed = config.shipSpeed;
    this.shipSystem.spawnTimer = 0.5;

    // Store special event chances
    this.emergencyChance = config.emergencyChance;
    this.treasureChance = config.treasureChance;
    this.emergencyTimer = 5 + Math.random() * 10;
    this.treasureTimer = 8 + Math.random() * 15;

    this.envSystem.setFogDensity(config.fogDensity);
    this.envSystem.setSkyColor(config.skyShift[0], config.skyShift[1], config.skyShift[2]);
    this.envSystem.setRainActive(config.hasRain);
    this.envSystem.setWindStrength(config.windStrength);

    this.waveHasStorm = config.stormChance > Math.random();
    if (this.waveHasStorm) {
      this.audioSystem.playStormWind();
      this.lightningTimer = 3 + Math.random() * 5;
    }

    // Reset beam energy for the new wave
    this.lighthouseSystem.resetEnergy();
    this.lighthouseSystem.setBeamActive(true);
    this.showState('playing');

    // Show wave start info
    this.showingWaveStart = true;
    this.waveStartTimer = 3.0;
    const difficulty = this.wave <= 3 ? 'CALM' : this.wave <= 6 ? 'ROUGH' : this.wave <= 9 ? 'STORM' : 'TEMPEST';
    const weather = config.hasRain ? (this.waveHasStorm ? '\u26a1 Thunder' : '\ud83c\udf27 Rain') : '\u2b50 Clear';
    this.hudPanel?.getElementById('wave-start-info')?.setProperties({
      text: `Wave ${this.wave} \u2022 ${difficulty} \u2022 ${weather} \u2022 ${config.shipCount} ships`,
    });

    this.updateHUD();
  }

  private getWaveConfig(wave: number): WaveConfig {
    const hasRain = wave >= 3 && Math.random() < Math.min(wave * 0.12, 0.8);
    const windStr = wave >= 4 ? Math.min((wave - 3) * 0.15, 1.0) : 0;
    const skyR = 0.01 + Math.min(wave * 0.005, 0.04);
    const skyG = 0.02 + Math.min(wave * 0.003, 0.03);
    const skyB = 0.06 + Math.min(wave * 0.005, 0.04);

    return {
      shipCount: 3 + wave * 2,
      spawnInterval: Math.max(1.5, 4 - wave * 0.3),
      shipSpeed: 0.6 + wave * 0.08,
      fogDensity: 0.012 + wave * 0.002,
      stormChance: Math.min(wave * 0.1, 0.7),
      hasRain,
      windStrength: windStr,
      skyShift: [skyR, skyG, skyB],
      emergencyChance: wave >= 3 ? Math.min((wave - 2) * 0.15, 0.6) : 0,
      treasureChance: wave >= 5 ? Math.min((wave - 4) * 0.1, 0.4) : 0,
    };
  }

  private updateHUD() {
    this.hudPanel?.getElementById('score')?.setProperties({ text: String(this.score) });
    this.hudPanel?.getElementById('lives')?.setProperties({ text: String(this.lives) });
    this.hudPanel?.getElementById('wave')?.setProperties({ text: String(this.wave) });
    const activeShips = this.shipSystem.getActiveShipCount() + this.shipSystem.shipsToSpawn;
    this.hudPanel?.getElementById('ships-remaining')?.setProperties({ text: String(activeShips) });

    // Beam energy bar
    const energy = this.lighthouseSystem.getBeamEnergy();
    const maxEnergy = this.lighthouseSystem.getMaxEnergy();
    const energyPct = Math.round((energy / maxEnergy) * 100);
    const beamText = this.lighthouseSystem.isOverheated() ? 'OVERHEAT' :
      this.lighthouseSystem.isBeamActive() ? `${energyPct}%` : `OFF ${energyPct}%`;
    this.hudPanel?.getElementById('beam-power')?.setProperties({ text: beamText });

    // Ship type counts
    const [f, c, p] = this.shipSystem.getShipCountByType();
    this.hudPanel?.getElementById('fishing-count')?.setProperties({ text: String(f) });
    this.hudPanel?.getElementById('cargo-count')?.setProperties({ text: String(c) });
    this.hudPanel?.getElementById('ferry-count')?.setProperties({ text: String(p) });

    // Special ships
    const [em, tr] = this.shipSystem.getSpecialShipCount();
    if (em > 0 || tr > 0) {
      const specials: string[] = [];
      if (em > 0) specials.push(`\ud83d\udea8${em}`);
      if (tr > 0) specials.push(`\ud83d\udcb0${tr}`);
      this.hudPanel?.getElementById('special-info')?.setProperties({ text: specials.join(' ') });
    } else {
      this.hudPanel?.getElementById('special-info')?.setProperties({ text: '' });
    }
  }

  private updateCompass() {
    const ships = this.shipSystem.getAllShips();
    const dirs = ['n', 'ne', 'e', 'se', 's', 'sw', 'w', 'nw'];
    const dirAngles = [
      Math.PI, 3 * Math.PI / 4, Math.PI / 2, Math.PI / 4,
      0, -Math.PI / 4, -Math.PI / 2, -3 * Math.PI / 4,
    ];
    const activeInDir: number[] = new Array(8).fill(-1);

    for (const ship of ships) {
      if (ship.docked || ship.sinking) continue;
      const pos = ship.entity.object3D!.position;
      const angle = Math.atan2(pos.x, pos.z);
      let bestIdx = 0;
      let bestDist = Infinity;
      for (let d = 0; d < 8; d++) {
        let diff = Math.abs(angle - dirAngles[d]);
        if (diff > Math.PI) diff = Math.PI * 2 - diff;
        if (diff < bestDist) {
          bestDist = diff;
          bestIdx = d;
        }
      }
      if (activeInDir[bestIdx] < ship.shipType) {
        activeInDir[bestIdx] = ship.shipType;
      }
    }

    // Colors: fishing=blue, cargo=orange, ferry=white, emergency=red, treasure=gold
    const typeColors = ['#4488cc', '#cc8844', '#ccccee', '#ff2222', '#ffcc00'];
    const inactiveColor = 'rgba(180, 200, 220, 0.5)';
    const inactiveBg = 'rgba(100, 120, 140, 0.3)';

    for (let d = 0; d < 8; d++) {
      const dirEl = this.compassPanel?.getElementById(`dir-${dirs[d]}`);
      const dotEl = this.compassPanel?.getElementById(`dot-${dirs[d]}`);
      if (activeInDir[d] >= 0) {
        const col = typeColors[Math.min(activeInDir[d], typeColors.length - 1)];
        dirEl?.setProperties({ color: col });
        dotEl?.setProperties({ backgroundColor: col });
      } else {
        dirEl?.setProperties({ color: inactiveColor });
        dotEl?.setProperties({ backgroundColor: inactiveBg });
      }
    }
  }

  private checkWaveComplete() {
    const ships = this.shipSystem.getAllShips();
    const allSpawned = this.shipSystem.shipsToSpawn <= 0;
    if (!allSpawned) return;

    let anyActive = false;
    let docked = 0;
    let sunk = 0;
    let dockedPoints = 0;
    for (const ship of ships) {
      if (ship.docked) {
        docked++;
        dockedPoints += ship.points;
      } else if (ship.sinking) {
        sunk++;
      } else {
        anyActive = true;
      }
    }

    // Also check for active special ships still in play
    const [em, tr] = this.shipSystem.getSpecialShipCount();
    if (em > 0 || tr > 0) anyActive = true;

    if (anyActive) return;

    // Wave done
    this.waveShipsSaved = docked;
    this.waveShipsLost = this.waveShipTotal - docked;

    // Score based on ship points
    const perfectBonus = this.waveShipsLost === 0 ? 500 : 0;
    const waveScore = dockedPoints + perfectBonus;
    this.score += waveScore;
    this.totalShipsSaved += docked;

    // Lose lives
    this.lives -= this.waveShipsLost;

    // Clear weather
    this.envSystem.setRainActive(false);
    this.envSystem.setWindStrength(0);

    if (this.lives <= 0) {
      this.gameOver();
      return;
    }

    this.audioSystem.playWaveComplete();
    const stars = this.waveShipsLost === 0 ? 3 : this.waveShipsLost <= 1 ? 2 : 1;
    const starStr = Array(stars).fill('\u2605').join(' ') +
      (stars < 3 ? ' ' + Array(3 - stars).fill('\u2606').join(' ') : '');

    this.waveCompletePanel?.getElementById('wave-num')?.setProperties({ text: `Wave ${this.wave}` });
    this.waveCompletePanel?.getElementById('ships-saved')?.setProperties({ text: String(docked) });
    this.waveCompletePanel?.getElementById('ships-lost')?.setProperties({ text: String(this.waveShipsLost) });
    this.waveCompletePanel?.getElementById('bonus')?.setProperties({ text: `+${perfectBonus}` });
    this.waveCompletePanel?.getElementById('stars')?.setProperties({ text: starStr });

    this.updateUpgradePanel();
    this.showState('wave-complete');
  }

  private gameOver() {
    this.audioSystem.playGameOver();
    this.envSystem.setRainActive(false);
    this.envSystem.setWindStrength(0);

    let isNewHigh = false;
    if (this.score > this.highScore) {
      this.highScore = this.score;
      localStorage.setItem('neon-lighthouse-high-score', String(this.highScore));
      isNewHigh = true;
    }
    if (this.wave > this.bestWave) {
      this.bestWave = this.wave;
      localStorage.setItem('neon-lighthouse-best-wave', String(this.bestWave));
    }

    this.gameOverPanel?.getElementById('final-score')?.setProperties({ text: String(this.score) });
    this.gameOverPanel?.getElementById('waves-survived')?.setProperties({ text: String(this.wave) });
    this.gameOverPanel?.getElementById('total-ships-saved')?.setProperties({ text: String(this.totalShipsSaved) });
    this.gameOverPanel?.getElementById('new-high-label')?.setProperties({
      text: isNewHigh ? 'NEW HIGH SCORE!' : ' ',
    });

    this.menuPanel?.getElementById('high-score')?.setProperties({ text: String(this.highScore) });
    this.menuPanel?.getElementById('best-wave')?.setProperties({ text: String(this.bestWave) });

    this.shipSystem.clearAllShips();
    this.showState('game-over');
  }

  update(delta: number, _time: number) {
    if (this.state === 'playing') {
      this.updateHUD();
      this.updateCompass();
      this.checkWaveComplete();

      // Wave start info fade
      if (this.showingWaveStart) {
        this.waveStartTimer -= delta;
        if (this.waveStartTimer <= 0) {
          this.showingWaveStart = false;
          this.hudPanel?.getElementById('wave-start-info')?.setProperties({ text: '' });
        }
      }

      // Periodic foghorn
      this.fogHornTimer -= delta;
      if (this.fogHornTimer <= 0) {
        this.audioSystem.playFoghorn();
        this.fogHornTimer = 15 + Math.random() * 10;
      }

      // Random lightning during storms
      if (this.waveHasStorm) {
        this.lightningTimer -= delta;
        if (this.lightningTimer <= 0) {
          this.envSystem.triggerLightning();
          this.audioSystem.playThunder();
          this.lightningTimer = 4 + Math.random() * 8;
        }
      }

      // Special event: emergency ship
      if (!this.emergencySpawned && this.emergencyChance > 0) {
        this.emergencyTimer -= delta;
        if (this.emergencyTimer <= 0 && Math.random() < this.emergencyChance) {
          this.shipSystem.spawnShip(3); // emergency type
          this.emergencySpawned = true;
          this.hudPanel?.getElementById('wave-start-info')?.setProperties({
            text: '\ud83d\udea8 EMERGENCY RESCUE \u2014 Ship in distress!',
          });
          this.showingWaveStart = true;
          this.waveStartTimer = 3.0;
        }
      }

      // Special event: treasure ship
      if (!this.treasureSpawned && this.treasureChance > 0) {
        this.treasureTimer -= delta;
        if (this.treasureTimer <= 0 && Math.random() < this.treasureChance) {
          this.shipSystem.spawnShip(4); // treasure type
          this.treasureSpawned = true;
          this.hudPanel?.getElementById('wave-start-info')?.setProperties({
            text: '\ud83d\udcb0 TREASURE BARGE spotted on the horizon!',
          });
          this.showingWaveStart = true;
          this.waveStartTimer = 3.0;
        }
      }
    }
  }
}

import { createSystem } from '@iwsdk/core';

export class AudioSystem extends createSystem({}) {
  private ctx!: AudioContext;
  private masterGain!: GainNode;
  private volumeOn = true;
  private initialized = false;
  private ambientOsc: OscillatorNode | null = null;
  private ambientGain: GainNode | null = null;

  // Ambient timers
  private seagullTimer = 5;
  private waveCrashTimer = 3;

  init() {
    const initAudio = () => {
      if (this.initialized) return;
      this.initialized = true;
      this.ctx = new AudioContext();
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 0.4;
      this.masterGain.connect(this.ctx.destination);
      this.startAmbient();
      document.removeEventListener('click', initAudio);
      document.removeEventListener('pointerdown', initAudio);
    };
    document.addEventListener('click', initAudio);
    document.addEventListener('pointerdown', initAudio);
  }

  private startAmbient() {
    if (!this.ctx) return;
    this.ambientOsc = this.ctx.createOscillator();
    this.ambientOsc.type = 'sine';
    this.ambientOsc.frequency.value = 40;
    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = 0.05;
    this.ambientOsc.connect(this.ambientGain);
    this.ambientGain.connect(this.masterGain);
    this.ambientOsc.start();
  }

  toggleVolume() {
    this.volumeOn = !this.volumeOn;
    if (this.masterGain) {
      this.masterGain.gain.value = this.volumeOn ? 0.4 : 0;
    }
  }

  isVolumeOn(): boolean {
    return this.volumeOn;
  }

  playFoghorn() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(80, now);
    osc.frequency.linearRampToValueAtTime(60, now + 2);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.15, now + 0.3);
    gain.gain.setValueAtTime(0.15, now + 1.5);
    gain.gain.linearRampToValueAtTime(0, now + 2.5);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 2.5);
  }

  playShipBell() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = 800;
    gain.gain.setValueAtTime(0.2, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.8);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.8);

    const osc2 = this.ctx.createOscillator();
    const gain2 = this.ctx.createGain();
    osc2.type = 'sine';
    osc2.frequency.value = 1000;
    gain2.gain.setValueAtTime(0.15, now + 0.15);
    gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.7);
    osc2.connect(gain2);
    gain2.connect(this.masterGain);
    osc2.start(now + 0.15);
    osc2.stop(now + 0.7);
  }

  playDockChime() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [523, 659, 784];
    for (let i = 0; i < notes.length; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = notes[i];
      const t = now + i * 0.12;
      gain.gain.setValueAtTime(0.2, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.6);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(t);
      osc.stop(t + 0.6);
    }
  }

  playCrashSound() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const bufferSize = this.ctx.sampleRate * 0.5;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufferSize * 0.2));
    }
    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.3, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 600;
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    noise.start(now);
    noise.stop(now + 0.5);

    const osc = this.ctx.createOscillator();
    const boomGain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(100, now);
    osc.frequency.exponentialRampToValueAtTime(30, now + 0.4);
    boomGain.gain.setValueAtTime(0.3, now);
    boomGain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);
    osc.connect(boomGain);
    boomGain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.4);
  }

  playWaveComplete() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [392, 494, 587, 659, 784];
    for (let i = 0; i < notes.length; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.value = notes[i];
      const t = now + i * 0.1;
      gain.gain.setValueAtTime(0.2, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(t);
      osc.stop(t + 0.5);
    }
  }

  playUIClick() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = 600;
    gain.gain.setValueAtTime(0.1, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.1);
  }

  playGameOver() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [440, 370, 311, 262];
    for (let i = 0; i < notes.length; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.value = notes[i];
      const t = now + i * 0.25;
      gain.gain.setValueAtTime(0.12, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(t);
      osc.stop(t + 0.5);
    }
  }

  playStormWind() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const bufferSize = this.ctx.sampleRate * 2;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * 0.5;
    }
    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.08, now + 0.5);
    gain.gain.setValueAtTime(0.08, now + 1.5);
    gain.gain.linearRampToValueAtTime(0, now + 2);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 400;
    filter.Q.value = 0.5;
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    noise.start(now);
    noise.stop(now + 2);
  }

  playThunder() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;

    // Low rumbling boom
    const bufferSize = this.ctx.sampleRate * 1.5;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      const env = Math.exp(-i / (bufferSize * 0.4));
      data[i] = (Math.random() * 2 - 1) * env;
    }
    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.25, now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.01, now + 1.5);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 300;
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    noise.start(now);
    noise.stop(now + 1.5);

    // Sub-bass
    const osc = this.ctx.createOscillator();
    const subGain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(50, now);
    osc.frequency.exponentialRampToValueAtTime(20, now + 1);
    subGain.gain.setValueAtTime(0.2, now);
    subGain.gain.exponentialRampToValueAtTime(0.001, now + 1);
    osc.connect(subGain);
    subGain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 1);
  }

  // New sounds

  playDistressHorn() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // Urgent two-tone horn
    for (let rep = 0; rep < 3; rep++) {
      const t = now + rep * 0.4;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(220, t);
      osc.frequency.linearRampToValueAtTime(280, t + 0.15);
      gain.gain.setValueAtTime(0.15, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(t);
      osc.stop(t + 0.3);
    }
  }

  playTreasureChime() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // Magical ascending sparkle
    const notes = [523, 659, 784, 1047, 1319];
    for (let i = 0; i < notes.length; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = notes[i];
      const t = now + i * 0.08;
      gain.gain.setValueAtTime(0.12, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(t);
      osc.stop(t + 0.4);
    }
  }

  playFlareSound() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // Rising whistle
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(400, now);
    osc.frequency.exponentialRampToValueAtTime(2000, now + 0.4);
    gain.gain.setValueAtTime(0.08, now);
    gain.gain.linearRampToValueAtTime(0.15, now + 0.2);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.5);

    // Pop at the top
    const pop = this.ctx.createOscillator();
    const popGain = this.ctx.createGain();
    pop.type = 'square';
    pop.frequency.value = 1500;
    popGain.gain.setValueAtTime(0.1, now + 0.35);
    popGain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
    pop.connect(popGain);
    popGain.connect(this.masterGain);
    pop.start(now + 0.35);
    pop.stop(now + 0.5);
  }

  playSeagull() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // Two-tone seagull cry
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(1200, now);
    osc.frequency.linearRampToValueAtTime(1600, now + 0.15);
    osc.frequency.linearRampToValueAtTime(1100, now + 0.4);
    osc.frequency.linearRampToValueAtTime(1400, now + 0.55);
    osc.frequency.linearRampToValueAtTime(900, now + 0.8);
    gain.gain.setValueAtTime(0.02, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.1);
    gain.gain.linearRampToValueAtTime(0.03, now + 0.4);
    gain.gain.linearRampToValueAtTime(0.04, now + 0.55);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.8);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.8);
  }

  playWaveCrash() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // Soft white noise burst for wave breaking
    const bufferSize = Math.floor(this.ctx.sampleRate * 1.5);
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      const env = Math.sin((i / bufferSize) * Math.PI);
      data[i] = (Math.random() * 2 - 1) * env * 0.3;
    }
    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.04, now + 0.3);
    gain.gain.linearRampToValueAtTime(0.06, now + 0.8);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 1.5);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 800;
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    noise.start(now);
    noise.stop(now + 1.5);
  }

  playUpgradeSound() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // Power-up ascending sweep
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(300, now);
    osc.frequency.exponentialRampToValueAtTime(900, now + 0.3);
    gain.gain.setValueAtTime(0.15, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.4);

    // Confirm chime
    const chime = this.ctx.createOscillator();
    const chimeGain = this.ctx.createGain();
    chime.type = 'sine';
    chime.frequency.value = 880;
    chimeGain.gain.setValueAtTime(0.12, now + 0.25);
    chimeGain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
    chime.connect(chimeGain);
    chimeGain.connect(this.masterGain);
    chime.start(now + 0.25);
    chime.stop(now + 0.6);
  }

  update(delta: number, _time: number) {
    if (!this.initialized) return;

    // Ambient seagull calls
    this.seagullTimer -= delta;
    if (this.seagullTimer <= 0) {
      this.playSeagull();
      this.seagullTimer = 8 + Math.random() * 15;
    }

    // Ambient wave crashes
    this.waveCrashTimer -= delta;
    if (this.waveCrashTimer <= 0) {
      this.playWaveCrash();
      this.waveCrashTimer = 5 + Math.random() * 10;
    }
  }
}

